import { expect, it } from 'vitest';
import { estimateVideoCost } from '@/billing/cost-estimation';
import { micros } from '@/billing/money';
import { snapDuration } from '@/motion/snap-duration';

// Synthetic rates characterize inherited pricing differences without any provider or database calls.
const model = 'seedance_v2_5';
const pricing = {
  'bytedance/seedance-2.5/image-to-video': { unitPrice: micros(1000), unit: '1000 tokens' },
  'bytedance/seedance-2.5/text-to-video': { unitPrice: micros(1000), unit: '1000 tokens' },
  'bytedance/seedance-2.5/reference-to-video': { unitPrice: micros(2000), unit: '1000 tokens' },
};
it.each([
  { name: 'smart model minimum', quoteDuration: snapDuration(undefined, model), expectedDuration: 4, expectedCost: 90720 },
  { name: 'add-video fixed duration', quoteDuration: 5, expectedDuration: 5, expectedCost: 113400 },
])('characterizes $name versus a 10s-shot', ({ quoteDuration, expectedDuration, expectedCost }) => {
  const executionDuration = snapDuration(10, model);
  expect([quoteDuration, executionDuration]).toEqual([expectedDuration, 10]);
  const opts = { pricing, resolution: '720p', hasReferenceImages: false } as const;
  expect(estimateVideoCost(model, quoteDuration, opts)).toBe(expectedCost);
  expect(estimateVideoCost(model, executionDuration, opts)).toBe(226800);
});
it.each([false, true])('characterizes omitted references with referenceOnly=%s', (referenceOnly) => {
  const opts = { pricing, resolution: '720p', referenceOnly } as const;
  expect(estimateVideoCost(model, 5, { ...opts, hasReferenceImages: false })).toBe(113400);
  expect(estimateVideoCost(model, 5, { ...opts, hasReferenceImages: true })).toBe(226800);
});
